INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT149-S4-Q3$batch10$, 149, 4, 3, $batch10$Main Conclusion$batch10$, $batch10$Restaurant owner: The newspaper reporter who panned my restaurant acknowledges having no special expertise about food and its preparation. His previous job was as a political reporter. He is a good writer, but he is not a true restaurant critic. A newspaper would never call someone a drama critic who had no special training in theater.$batch10$, $batch10$Which one of the following most accurately expresses the conclusion drawn in the restaurant owner’s argument?$batch10$, $batch10$D$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=149 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT149-S4-Q3$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$The newspaper reporter who panned the restaurant acknowledges having no special expertise about food and its preparation.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT149-S4-Q3$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$The previous job of the newspaper reporter who panned the restaurant was as a political reporter.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT149-S4-Q3$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$The newspaper reporter who panned the restaurant is a good writer.$batch10$, $batch10$Concession$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT149-S4-Q3$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$The newspaper reporter who panned the restaurant is not a true restaurant critic.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT149-S4-Q3$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$A newspaper would never call someone a drama critic who had no special training in theater.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT149-S4-Q3$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT149-S4-Q3$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$The reporter who panned the restaurant is not a true restaurant critic.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The reporter admits having no special expertise about food and previously covered politics. A newspaper would never call someone without theater training a drama critic.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The fourth sentence grants that the reporter is a good writer, then says "but" the reporter is not a true critic. The concession comes first and the conclusion follows "but." The other sentences support it, and the drama critic analogy backs it up.$batch10$), (3, $batch10$Goal$batch10$, $batch10$The reporter is not a true restaurant critic.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT149-S4-Q3$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This supports the conclusion. No expertise means not a real critic.$batch10$), ($batch10$B$batch10$, $batch10$This also supports the conclusion.$batch10$), ($batch10$C$batch10$, $batch10$The owner grants this before the "but."$batch10$), ($batch10$D$batch10$, $batch10$This is the claim after the "but" that the rest supports.$batch10$), ($batch10$E$batch10$, $batch10$This is an analogy used as support.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT149-S4-Q3$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
